<?php
namespace qqworld_collector\module; use qqworld_collector\lib; class cloudStorage extends cloud_storage { var $guid; var $label; var $applied; var $is_current; var $accessed = false; var $mode = 'fast'; var $deploied = false; var $auto_replace = true; var $priority = 99; var $log_id = 'cloud-storage'; var $className; var $field_name; var $core; var $enabled; var $host; var $protocol; var $folder; var $homepage; var $domain; var $custom_upload_dir; var $sync_delete; var $silent_scanning; var $delete_attachment_after_synced; var $username; var $password; var $bucket; var $token; var $home; var $custom_replacement; var $endpoint; var $allowed_image_types; public function __construct() { add_filter( 'qqworld-collector-cloud-storage-mode', array($this, 'add_cloud_storage_mode') ); add_action( 'qqworld-collector-cloud-storage-form', array($this, 'add_could_storage_form') ); add_action( 'admin_init', array($this, 'common') ); add_action( 'load_textdomain', array($this, 'deploy') ); add_filter( 'qqworld-collector-cloud-storage-settings', array($this, 'cloud_storage_settings') ); add_action( 'admin_init', array($this, 'initial') ); } public function init() { } public function initial() { $this->allowed_image_types = $this->get_mime_types(); } public function is_excluded($source_path) { if (!empty($this->options->cloud_storage_exclude_path)) foreach ($this->options->cloud_storage_exclude_path as $path) { if (strstr($source_path, $path) !== false) return true; } return false; } public function getFormData($source_path, $mimeType, $postDatas, $headers = array()) { $mimeBoundary = '----WebKitFormBoundary' . uniqid(); $data = array(); foreach ($postDatas as $postData) { $name = $postData['name']; $value = $postData['value']; array_push($data, '--' . $mimeBoundary); if (isset($postData['filename'])) { array_push($data, "Content-Disposition: form-data; name=\"{$name}\"; filename=\"{$postData['filename']}\""); array_push($data, "Content-Type: $mimeType"); } else { array_push($data, "Content-Disposition: form-data; name=\"{$name}\""); } array_push($data, ''); array_push($data, $value); } array_push($data, '--' . $mimeBoundary . "--"); $post_data = implode("\r\n", $data); $length = strlen($post_data); array_push($headers, "Connection: close"); array_push($headers, "Content-Type: multipart/form-data; boundary={$mimeBoundary}"); array_push($headers, "Content-Length: {$length}"); return array($post_data, $headers); } public function get_all_attachment_count() { if (!isset($GLOBALS['ALL_ATTACHMENT_COUNT'])) { global $wpdb; $sql = "SELECT COUNT(*) FROM `{$wpdb->posts}` WHERE `post_type`='attachment'"; $GLOBALS['ALL_ATTACHMENT_COUNT'] = $wpdb->get_var($sql); } return $GLOBALS['ALL_ATTACHMENT_COUNT']; } public function get_synced_attachment_count($guid=null) { global $wpdb; $guid = $guid ? $guid : $this->guid; $guid = str_replace('-', '_', $guid); $sql = "SELECT COUNT(*) FROM `{$wpdb->posts}` WHERE `post_type`='attachment' AND `ID` IN (SELECT `post_id` FROM `{$wpdb->postmeta}` WHERE `meta_key`='_sync_{$guid}' AND `meta_value`='1')"; $count = $wpdb->get_var($sql); return $count; } public function add_cloud_storage_mode($modes) { $modes[$this->guid] = $this->label; return $modes; } public function add_could_storage_form($guid) { ?>
