 } public function cloud_storage_settings($values) { if (isset($values['mode'])) { $guid = $values['mode']; if ( isset($values[$guid]) ) { if (isset($values[$guid]['host'])) { $values[$guid]['host'] = trim($values[$guid]['host']); switch ($guid) { case 'chevereto': case 'caihong': case 'lsky': case 'hidove': if (!preg_match('/^(https?:)?\/\//i', $values[$guid]['host'])) $values[$guid]['host'] = 'http://' . $values[$guid]['host']; $values[$guid]['host'] = preg_replace("/\/*$/", '', $values[$guid]['host']); break; case 'local': case 'ftp': case 'kodexplorer': case 'minio': $values[$guid]['host'] = preg_replace(array("/^https?:/i", "/^\/*/", "/\/*$/"), '', $values[$guid]['host']); break; default: $values[$guid]['host'] = preg_replace(array("/(\/[^\/]*)*?$/i", "/^https?:/i", "/^\/*/", "/\/*$/"), '', $values[$guid]['host']); break; } } if (isset($values[$guid]['folder'])) { if (!preg_match('/^\//', $values[$guid]['folder'], $match)) { $values[$guid]['folder'] = '/' . $values[$guid]['folder']; } else { $values[$guid]['folder'] = preg_replace("/^\/*/", '/', $values[$guid]['folder']); } $values[$guid]['folder'] = preg_replace("/\/*$/", '', $values[$guid]['folder']); } } } return $values; } public function common() { if ( isset($_POST['enabled_cloud_storage']) ) { $this->enabled = isset($_POST['enabled_cloud_storage']) && $_POST['enabled_cloud_storage'] == 1; } else { $this->enabled = $this->options->cloud_storage_enabled; } if ($this->enabled && $this->options->cloud_storage_mode == $this->guid && !$this->deploied) { $this->deploied = true; do_action( 'qqworld-collector-cloud-storage-common-hook', $this ); } if ( apply_filters( 'qqworld-collector-activated-module-' . 'cloud-storage', false) ) add_filter( 'qqworld-collector-sdks', array($this, 'external_sdk') ); } public function external_sdk($sdks) { return $sdks; } public function __call($name, $arguments) {} public function add_exlude_domain($exclude_domain) { if (!is_array($exclude_domain)) $exclude_domain = array(); if ($this->options->cloud_storage_joinmode_enabled) { if (!empty($this->options->cloud_storage_jsonmode_selected)) foreach ($this->options->cloud_storage_jsonmode_selected as $guid) { $className = str_replace('-', '_', $guid); if (is_array($this->core->$className->host)) { $exclude_domain = array_merge($exclude_domain, $this->core->$className->host); } else { $exclude_domain[] = $this->core->$className->host; } } } elseif (!empty($this->host)) { if (is_array($this->host)) { $exclude_domain = array_merge($exclude_domain, $this->host); } else { $exclude_domain[] = $this->host; } } return $exclude_domain; } public function manage_media_columns( $cols ) { if ($this->options->cloud_storage_joinmode_enabled) { $cols['cloud-storage'] = __('JoinMode of Cloud Storage', $this->text_domain); } else { $cols['cloud-storage'] = $this->label; } return $cols; } public function manage_media_custom_column( $column_name, $id ) { switch ($column_name) { case 'cloud-storage': if ($this->options->cloud_storage_joinmode_enabled) { $cloud_storages = array(); foreach ($GLOBALS['QC']->cloud_storage->cloud_storages as $guid => $label) { $className = str_replace('-', '_', $guid); $synced = get_post_meta($id, "_sync_{$className}", true); if ($synced) $cloud_storages[$guid] = $label; } if (!empty($cloud_storages)) { print '<button type="button" data-id="'.$id.'" class="button cloud-storage-sync qc-icon export">'.__('Sync Again', $this->text_domain).'</button>'; print ' <button type="button" data-id="'.$id.'" class="button cloud-storage-speed-detection qc-icon refresh">'.__('Speed Detection', $this->text_domain).'</button>'; print '<dl class="synchronized-cloud-storages-list"><dt>'.__('Synchronized cloud storages', $this->text_domain).'</dt>'; foreach ($cloud_storages as $guid => $label) { print '<dd>' . $label . ' <a href="#" class="delete-cloud-storage qc-icon delete" data-id="'.$id.'" data-guid="'.$guid.'">'.__('Delete').'</a></dd>'; } print '</dl>'; } else { echo '<button type="button" data-id="'.$id.'" class="button button-primary cloud-storage-sync qc-icon export">'.__('Sync Now', $this->text_domain).'</button>'; } } else { $this->apply_manage_media_custom_column($id); } break; } } public function apply_manage_media_custom_column($id) {} public function deploy() {} public function image_send_to_editor($html, $id, $caption, $title, $align, $url, $size, $alt) { return $html; } public function image_downsize($downsize, $id, $size) { if (!isset($GLOBALS['JSONMODE']) && $this->options->cloud_storage_joinmode_enabled) { if (is_array($size)) { $sizeStr = implode('x', $size); $width = $size[0]; $height = $size[1]; $is_intermediate = false; } else { $sizeStr = $size; $metadata = wp_get_attachment_metadata( $id ); $sizes = $metadata ? $metadata['sizes'] : array(); if (!isset($sizes[$size])) { $width = isset($metadata['width']) ? $metadata['width'] : 0; $height = isset($metadata['height']) ? $metadata['height'] : 0; } else { $width = isset($sizes[$size]['width']) ? $sizes[$size]['width'] : ''; $height = isset($sizes[$size]['height']) ? $sizes[$size]['height'] : ''; } $is_intermediate = $size == 'full' ? false : true; } $joinmode_url = $this->get_joinmode_url($id, $sizeStr); if ($joinmode_url) $url = $joinmode_url; $downsize = array($url, $width, $height, $is_intermediate); } else { $classname = get_post_meta($id, '_splitted_guid', true); if ($classname) { $downsize = $this->core->$classname->apply_image_downsize($downsize, $id, $size); } else { $downsize = $this->apply_image_downsize($downsize, $id, $size); } } $this->applied = true; return $id ? $downsize : false; } public function apply_image_downsize($downsize, $id, $size) {} public function wp_get_attachment_url($url, $post_id) { if (!isset($GLOBALS['JSONMODE']) && $this->options->cloud_storage_joinmode_enabled) { $joinmode_url = $this->get_joinmode_url($post_id); if ($joinmode_url) $url = $joinmode_url; } else { $classname = get_post_meta($post_id, '_splitted_guid', true); if ($classname) { $url = $this->core->$classname->apply_wp_get_attachment_url($url, $post_id); } else { $url = $this->apply_wp_get_attachment_url($url, $post_id); } } return $url; } public function apply_wp_get_attachment_url($url, $post_id) {} public function wp_get_attachment_image_src($image, $attachment_id, $size, $icon) { if (!isset($GLOBALS['JSONMODE']) && $this->options->cloud_storage_joinmode_enabled) { $joinmode_url = $this->get_joinmode_url($attachment_id); if ($joinmode_url) $image[0] = $joinmode_url; } else { $classname = get_post_meta($attachment_id, '_splitted_guid', true); if ($classname) { $image = $this->core->$classname->apply_wp_get_attachment_image_src($image, $attachment_id, $size, $icon); } else { $image = $this->apply_wp_get_attachment_image_src($image, $attachment_id, $size, $icon); } } return $image; } public function apply_wp_get_attachment_image_src($image, $attachment_id, $size, $icon) {} public function wp_calculate_image_srcset($sources, $size_array, $image_src, $image_meta, $attachment_id) { if (!isset($GLOBALS['JSONMODE']) && $this->options->cloud_storage_joinmode_enabled) { foreach ($sources as &$source) { $size = $source['value'] . 'x' . $source['value']; $joinmode_url = $this->get_joinmode_url($attachment_id, $size); if ($joinmode_url) $source['url'] = $joinmode_url; } } else { $classname = get_post_meta($attachment_id, '_splitted_guid', true); if ($classname) { $sources = $this->core->$classname->apply_wp_calculate_image_srcset($sources, $size_array, $image_src, $image_meta, $attachment_id); } else { $sources = $this->apply_wp_calculate_image_srcset($sources, $size_array, $image_src, $image_meta, $attachment_id); } } return $sources; } public function apply_wp_calculate_image_srcset($sources, $size_array, $image_src, $image_meta, $attachment_id) { return $sources; } public function wp_calculate_image_srcset_meta($image_meta, $size_array, $image_src, $attachment_id) { if ($this->options->cloud_storage_joinmode_enabled) { $image_meta['file'] = 'cs/v1/'. $attachment_id; } else { $classname = get_post_meta($attachment_id, '_splitted_guid', true); if ($classname) { $sources = $this->core->$classname->apply_wp_calculate_image_srcset_meta($image_meta, $size_array, $image_src, $attachment_id); } else { $image_meta = $this->apply_wp_calculate_image_srcset_meta($image_meta, $size_array, $image_src, $attachment_id); } } return $image_meta; } public function apply_wp_calculate_image_srcset_meta($image_meta, $size_array, $image_src, $attachment_id) { return $image_meta; } public function cloud_thumbnail_arguments($arguments, $size) { return $arguments; } public function do_sync_single_attachment($attachment_id, $metadata = null) { $this->mode = isset($_POST['mode']) ? $_POST['mode'] : 'fast'; $metadata = $metadata ? $metadata : wp_get_attachment_metadata($attachment_id); $results = array(); if ( $this->options->cloud_storage_joinmode_enabled ) { if ( !empty($this->options->cloud_storage_jsonmode_selected) ) { $mime_type = get_post_mime_type($attachment_id); $type = preg_replace('/\/.*/i', '', strtolower($mime_type)); $allowed = isset($this->options->cloud_storage_joinmode_types[$type]) ? $this->options->cloud_storage_joinmode_types[$type] : false; foreach ($this->options->cloud_storage_jsonmode_selected as $guid) { if ($allowed != 'all' && (empty($allowed) || $guid != $allowed) ) continue; $classname = str_replace('-', '_', $guid); $this->core->$classname->is_current = true; $result = $this->core->$classname->sync($metadata, $attachment_id, false); $results[] = $result; } foreach ($results as $result) { if ($result['success']) { $synced_attachment_ids = $GLOBALS['QC']->cache->get_cache('synced-attachment-ids'); if ($synced_attachment_ids) { $synced_attachment_ids .= "\n" . $attachment_id; } else { $synced_attachment_ids = $attachment_id; } $GLOBALS['QC']->cache->set_cache('synced-attachment-ids', $synced_attachment_ids); break; } } $this->joinmode_auto_replace($attachment_id, $metadata); } } else { $mime_type = get_post_mime_type($attachment_id); $type = preg_replace('/\/.*/i', '', strtolower($mime_type)); $split = isset($this->options->cloud_storage_generalmode_types[$type]) ? $this->options->cloud_storage_generalmode_types[$type] : false; if ($split) { $classname = str_replace('-', '_', $split); $this->core->$classname->is_current = true; $results = $this->core->$classname->sync($metadata, $attachment_id, $this->auto_replace); update_post_meta($attachment_id, '_splitted_guid', $classname ); } else { $results = $this->sync($metadata, $attachment_id, $this->auto_replace); update_post_meta($attachment_id, '_splitted_guid', '' ); } } return $results; } public function joinmode_auto_replace($attachment_id, $metadata = null ) { global $wpdb; remove_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), $this->priority ); remove_filter( 'image_downsize', array($this, 'image_downsize'), $this->priority ); remove_filter( 'wp_get_attachment_image_src', array($this, 'wp_get_attachment_image_src'), $this->priority ); do_action( 'qqworld-collector-log', $this->log_id, 'Joinmode Auto Replace ($metadata):', print_r($metadata, true) ); $queues = array(); $type = get_post_mime_type($attachment_id); do_action( 'qqworld-collector-log', $this->log_id, 'Joinmode Auto Replace ($type):', print_r($type, true) ); if (in_array($type, $this->allowed_image_types)) { $sizes = array('full'); if (isset($metadata['sizes']) && !empty($metadata['sizes'])) { $sizes = array_merge(array_keys($metadata['sizes']), $sizes); } foreach ($sizes as $size) { $source_url = wp_get_attachment_image_src($attachment_id, $size); $joinmode_url = $size == 'full' ? $this->get_joinmode_url($attachment_id) : $this->get_joinmode_url($attachment_id, $size); $queues[$size] = array( 'source_url' => $source_url[0], 'destination_url' => $joinmode_url ? $joinmode_url : $source_url ); } } else { $attachment_url = wp_get_attachment_url($attachment_id); $joinmode_url = $this->get_joinmode_url($attachment_id); $queues['file'] = array( 'source_url' => $attachment_url, 'destination_url' => $joinmode_url ? $joinmode_url : $attachment_url ); } do_action( 'qqworld-collector-log', $this->log_id, 'Joinmode Auto Replace ($queues):', print_r($queues, true) ); if (!empty($queues)) foreach ($queues as $queue) { $source_url = $queue['source_url']; $destination_url = $queue['destination_url']; if (!empty($source_url) && !empty($destination_url)) { $sql = "UPDATE `{$wpdb->posts}` SET `post_content` = REPLACE(`post_content`, '{$source_url}', '{$destination_url}')"; $wpdb->query($sql); } } add_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), $this->priority, 2 ); add_filter( 'image_downsize', array($this, 'image_downsize'), $this->priority, 3 ); add_filter( 'wp_get_attachment_image_src', array($this, 'wp_get_attachment_image_src'), $this->priority, 4 ); } public function sync_single_attachment() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; $attachment_id = $_POST['attachment_id']; $results = $this->do_sync_single_attachment($attachment_id); echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function silent_scanning() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; set_time_limit($this->options->qc_stress_timeout); $guid = str_replace('-', '_', $_POST['guid']); $mode = $_POST['mode']; for ($paged=0; $paged<99999999; $paged++) { switch ($mode) { case 'fast': $args = array( 'post_type' => 'attachment', 'post_mime_type' => $this->options->cloud_storage_filetypes, 'meta_key' => "_sync_{$guid}", 'meta_value' => 1, 'meta_compare' => 'NOT EXISTS', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); break; case 'smart': $args = array( 'post_type' => 'attachment', 'post_mime_type' => $this->options->cloud_storage_filetypes, 'posts_per_page' => 1000, 'offset' => 1000*$paged ); break; } $attachments = get_posts($args); if (!empty($attachments)) { foreach ($attachments as $attachment) { $attachment_id = $attachment->ID; $metadata = wp_get_attachment_metadata($attachment_id); $results = $this->sync($metadata, $attachment_id, $this->auto_replace); } } else { $results = array( 'success' => 1, 'msg' => __('Congratulations, seems like all attachments had already synced.', $this->text_domain) ); break; } } print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function no_media_library_attachment($remote_attachment, $type) { return $remote_attachment; } public function includes() {} public function access_service() {} public function upload($destination_path, $source_path) {} public function upload_single_file($url, $destination_path = null) { if ( $this->options->cloud_storage_joinmode_enabled ) return; if ($this->enabled) { $uploads = get_option( 'qqworld-collector-cloud-storage-record-uploads' ); if ($uploads && isset($uploads[$url])) { $response = wp_remote_head($uploads[$url], array( 'headers' => array( 'referer' => home_url() ) )); $response_code = wp_remote_retrieve_response_code($response); if ($response_code == 200) return $uploads[$url]; } do_action( 'qqworld-collector-log', $this->log_id, 'Start upload single file API ($url):', print_r($url, true) ); if ($destination_path) do_action( 'qqworld-collector-log', $this->log_id, 'Start upload single file API ($destination_path):', print_r($destination_path, true) ); $temp = ''; if ( strstr($url, home_url())!== false ) { $destination_path = $destination_path ? $destination_path : str_replace(home_url(), '', $url); $source_path = preg_replace('/\/$/i', '', ABSPATH) . str_replace(home_url(), '', $url); if ($this->is_excluded($source_path)) return $url; } else { $destination_path = $destination_path ? $destination_path : preg_replace('/^(http)?s?:?\/\//i', '', $url); $tmp_dir = get_temp_dir(); $source_path = $tmp_dir . basename($url); if ($this->is_excluded($source_path)) return $url; $temp = fopen($source_path, "w"); fwrite($temp, file_get_contents($url)); } if (!preg_match('/^\//', $destination_path)) $destination_path = '/